#!/usr/bin/env python3
"""Deterministic extraction of checkable claims from Digest chapter 1. Stdlib only.

    python digest_check/claims.py            # writes private/claims.json, prints a summary

The chapter is read from git, never from a checkout of the branch:
    git -C ~/DEV/Performance_Playbook show origin/digest-start:docs/digest/ch01_forcedecks_cmj.md

Rules, in order:
  * Only the procedure sections are read: Setup, Preparing the athlete, Testing protocol,
    Data quality checks, Troubleshooting, Data management and export, Teardown and
    storage. The short version, the purpose section, the owner table, contacts, revision
    history and open questions are skipped (summary, metadata, or not procedure).
  * A paragraph becomes one claim per sentence. A list item is one claim (its sentences
    kept together). A table row is one claim: header: cell, for each non-empty cell.
  * Any sentence that touches a [CONFIRM: ...] span is dropped. Sentences are split
    BEFORE that filter, so a paragraph or item keeps its other sentences.
  * Sentences about the document itself ("this chapter", "the handbook chapter") and the
    "Photo to add" line are dropped.
Claim ids are c01, c02, ... in document order, so the same chapter gives the same ids.
"""
from __future__ import annotations

import hashlib
import json
import re
import subprocess
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
PRIVATE = HERE / "private"
REPO = Path.home() / "DEV" / "Performance_Playbook"
REF = "origin/digest-start:docs/digest/ch01_forcedecks_cmj.md"

INCLUDE = {"Setup", "Preparing the athlete", "Testing protocol", "Data quality checks",
           "Troubleshooting", "Data management and export", "Teardown and storage"}
META = re.compile(r"\bthis chapter\b|\bhandbook chapter\b|\buntil it ships\b|^Photo to add", re.I)
SENT = re.compile(r'(?<=[.!?])\s+(?=[A-Z"(\[])|(?<=[.!?]")\s+(?=[A-Z])')
SHORT = 7  # a sentence under this many words is a lead-in; it joins the next one


def chapter_text() -> str:
    return subprocess.run(["git", "-C", str(REPO), "show", REF], check=True,
                          capture_output=True, text=True).stdout


def clean(s: str) -> str:
    s = s.replace("**", "").replace("`", "")
    return re.sub(r"\s+", " ", s).strip()


def sentences(text: str) -> list[str]:
    """Split, then drop any sentence overlapping a [CONFIRM ...] span."""
    text = clean(text)
    spans = [(m.start(), m.end()) for m in re.finditer(r"\[CONFIRM[^\]]*\]?", text)]
    kept, pos = [], 0
    for part in SENT.split(text):
        start = text.index(part, pos)
        end = start + len(part)
        pos = end
        if any(s < end and e > start for s, e in spans):
            continue
        if META.search(part) or not re.search(r"[A-Za-z]{3}", part):
            continue
        kept.append(part.strip())
    out, carry = [], ""
    for part in kept:
        part = f"{carry} {part}".strip()
        carry = ""
        if len(part.split()) < SHORT and part is not kept[-1]:
            carry = part
            continue
        out.append(part)
    if carry:
        out.append(carry)
    # A bare lead-in ("After every session:") with nothing after it says nothing.
    return [s for s in out if not (s.endswith(":") and len(s.split()) < SHORT)]


def blocks(md: str):
    """Yield (section, kind, text) for paragraphs, list items and table rows."""
    h2 = h3 = None
    para: list[str] = []
    item: list[str] | None = None
    header: list[str] | None = None

    def flush():
        nonlocal para, item
        if para:
            yield (h2, h3, "para", " ".join(para))
            para = []
        if item is not None:
            yield (h2, h3, "item", " ".join(item))
            item = None

    for line in md.splitlines():
        if line.startswith("#"):
            yield from flush()
            header = None
            level = len(line) - len(line.lstrip("#"))
            title = line.lstrip("#").strip()
            if level == 2:
                h2, h3 = title, None
            elif level == 3:
                h3 = title
            continue
        if not line.strip():
            yield from flush()
            continue
        if line.startswith("|"):
            yield from flush()
            cells = [c.strip() for c in line.strip().strip("|").split("|")]
            if all(re.fullmatch(r":?-+:?", c) for c in cells):
                continue
            if header is None:
                header = cells
                continue
            yield (h2, h3, "row", list(zip(header, cells)))
            continue
        header = None
        m = re.match(r"\s*(?:[-*]|\d+\.)\s+(.*)", line)
        if m:
            yield from flush()
            item = [m.group(1)]
        elif item is not None and line.startswith(" "):
            item.append(line.strip())
        else:
            if item is not None:
                yield from flush()
            para.append(line.strip())
    yield from flush()


def extract(md: str) -> list[dict]:
    claims = []
    for h2, h3, kind, body in blocks(md):
        if h2 not in INCLUDE:
            continue
        section = f"{h2} > {h3}" if h3 else h2
        if kind == "para":
            texts = sentences(body)
        elif kind == "item":
            kept = sentences(body)
            texts = [" ".join(kept)] if kept else []
        else:  # table row
            parts = []
            for name, cell in body:
                kept = sentences(cell)
                if kept:
                    parts.append(f"{name}: {' '.join(kept)}")
            texts = ["; ".join(parts)] if len(parts) >= 2 else []
        for t in texts:
            claims.append({"id": f"c{len(claims) + 1:02d}", "section": section,
                           "kind": kind, "text": t})
    return claims


def main() -> int:
    md = chapter_text()
    claims = extract(md)
    PRIVATE.mkdir(exist_ok=True)
    (PRIVATE / "claims.json").write_text(json.dumps(
        {"ref": REF, "sha256": hashlib.sha256(md.encode()).hexdigest(), "claims": claims},
        indent=1, ensure_ascii=False), encoding="utf-8")
    for c in claims:
        print(f"{c['id']} [{c['section'][:28]:<28}] {c['text'][:110]}")
    print(f"\n{len(claims)} claims; chapter sha256 {hashlib.sha256(md.encode()).hexdigest()[:16]}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
